import React, { useState, useRef } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { X, Upload, Film, Play, Check, AlertTriangle, Loader2, Lock } from 'lucide-react';
import { GoogleGenAI } from "@google/genai";
import { CyberButton } from './ui/CyberComponents';

interface AdminPanelProps {
  isOpen: boolean;
  onClose: () => void;
  onUpdateHero: (mediaType: 'image' | 'video', src: string) => void;
}

const AdminPanel: React.FC<AdminPanelProps> = ({ isOpen, onClose, onUpdateHero }) => {
  const [activeTab, setActiveTab] = useState<'upload' | 'generate'>('upload');
  const [selectedImage, setSelectedImage] = useState<string | null>(null);
  const [prompt, setPrompt] = useState("Cyberpunk character portrait, breathing, subtle movement, neon lighting, high tech city background, 8k resolution, cinematic");
  const [isGenerating, setIsGenerating] = useState(false);
  const [generatedVideoUrl, setGeneratedVideoUrl] = useState<string | null>(null);
  const [status, setStatus] = useState<string>('');
  const [error, setError] = useState<string | null>(null);
  const [success, setSuccess] = useState<string | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onload = (event) => {
        setSelectedImage(event.target?.result as string);
        setActiveTab('generate');
        setSuccess('Source image uploaded successfully.');
        setTimeout(() => setSuccess(null), 3000);
      };
      reader.readAsDataURL(file);
    }
  };

  const ensureApiKey = async () => {
    // @ts-ignore - aistudio is injected
    if (window.aistudio && window.aistudio.hasSelectedApiKey) {
       // @ts-ignore
       const hasKey = await window.aistudio.hasSelectedApiKey();
       if (!hasKey) {
          setStatus("Requesting Access Clearance...");
          // @ts-ignore
          await window.aistudio.openSelectKey();
          // Race condition mitigation: Assume key selection was successful and proceed.
       }
    }
    return true;
  };

  const generateVideo = async () => {
    if (!selectedImage) return;

    try {
      setError(null);
      setSuccess(null);
      setIsGenerating(true);
      setStatus('Initializing Neural Link...');

      await ensureApiKey();

      // Always create a new instance right before the call to pick up the key
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

      // Clean base64 string and get correct mime type
      const [header, base64Data] = selectedImage.split(',');
      const mimeType = header.match(/:(.*?);/)?.[1] || 'image/jpeg';

      setStatus(`Uploading Source Data (${mimeType}) to Veo Model...`);

      let operation = await ai.models.generateVideos({
        model: 'veo-3.1-fast-generate-preview',
        prompt: prompt,
        image: {
          imageBytes: base64Data,
          mimeType: mimeType, 
        },
        config: {
          numberOfVideos: 1,
          resolution: '720p', // Fast preview
          aspectRatio: '9:16' // Portrait for the avatar slot
        }
      });

      setStatus('Processing Simulation (This may take a moment)...');

      // Poll for completion - Veo takes time, check every 10s
      while (!operation.done) {
        await new Promise(resolve => setTimeout(resolve, 10000));
        operation = await ai.operations.getVideosOperation({operation: operation});
        setStatus('Rendering Frames...');
      }

      if (operation.error) {
          throw new Error(operation.error.message || "Unknown generation error");
      }

      // Check both response and result properties for robustness
      // @ts-ignore - accessing potential alternate property
      const videoUri = operation.response?.generatedVideos?.[0]?.video?.uri || operation.result?.generatedVideos?.[0]?.video?.uri;

      if (!videoUri) {
          console.error("Operation result full dump:", JSON.stringify(operation, null, 2));
          throw new Error("No video URI returned. The content may have been blocked by safety filters.");
      }

      setStatus('Downloading Final Artifact...');
      const videoResponse = await fetch(`${videoUri}&key=${process.env.API_KEY}`);
      const videoBlob = await videoResponse.blob();
      const videoUrl = URL.createObjectURL(videoBlob);

      setGeneratedVideoUrl(videoUrl);
      setStatus('Generation Complete.');
      setSuccess('Video simulation generated successfully.');
      setTimeout(() => setSuccess(null), 4000);

    } catch (err: any) {
      console.error(err);
      setError(err.message || "An error occurred during generation");
    } finally {
      setIsGenerating(false);
    }
  };

  const applyToHeader = () => {
    if (generatedVideoUrl) {
        onUpdateHero('video', generatedVideoUrl);
        setSuccess('Header system updated. Closing console...');
        setTimeout(() => {
            setSuccess(null);
            onClose();
        }, 1500);
    }
  };

  return (
    <AnimatePresence>
      {isOpen && (
        <motion.div
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
            className="fixed inset-0 z-[100] flex items-center justify-center bg-black/80 backdrop-blur-sm p-4"
        >
            <motion.div
                initial={{ scale: 0.9, y: 20 }}
                animate={{ scale: 1, y: 0 }}
                exit={{ scale: 0.9, y: 20 }}
                className="w-full max-w-4xl bg-black border border-yellow-500/30 rounded-lg shadow-[0_0_50px_rgba(234,179,8,0.1)] overflow-hidden flex flex-col max-h-[90vh]"
            >
                {/* Header */}
                <div className="flex items-center justify-between p-4 border-b border-yellow-500/20 bg-zinc-900/50">
                    <div className="flex items-center gap-3">
                        <Lock className="w-5 h-5 text-yellow-500" />
                        <h2 className="text-xl font-bold text-white font-orbitron tracking-wider">ADMIN_CONSOLE // <span className="text-yellow-500">VEO_GENERATOR</span></h2>
                    </div>
                    <button onClick={onClose} className="p-2 hover:bg-white/10 rounded-full transition-colors text-gray-400 hover:text-white">
                        <X size={24} />
                    </button>
                </div>

                <div className="flex flex-1 overflow-hidden">
                    {/* Sidebar */}
                    <div className="w-64 border-r border-white/10 bg-black/50 p-4 hidden md:flex flex-col gap-2">
                        <button 
                            onClick={() => setActiveTab('upload')}
                            className={`flex items-center gap-3 p-3 rounded text-left transition-all ${activeTab === 'upload' ? 'bg-yellow-500 text-black font-bold' : 'text-gray-400 hover:bg-white/5'}`}
                        >
                            <Upload size={18} />
                            UPLOAD SOURCE
                        </button>
                        <button 
                            onClick={() => setActiveTab('generate')}
                            disabled={!selectedImage}
                            className={`flex items-center gap-3 p-3 rounded text-left transition-all ${activeTab === 'generate' ? 'bg-yellow-500 text-black font-bold' : 'text-gray-400 hover:bg-white/5'} ${!selectedImage ? 'opacity-50 cursor-not-allowed' : ''}`}
                        >
                            <Film size={18} />
                            GENERATE VIDEO
                        </button>
                    </div>

                    {/* Main Content */}
                    <div className="flex-1 p-6 overflow-y-auto bg-zinc-950/50 relative">
                        {/* Scanline overlay */}
                        <div className="absolute inset-0 pointer-events-none opacity-10 bg-[linear-gradient(rgba(18,16,10,0)_50%,rgba(0,0,0,0.25)_50%),linear-gradient(90deg,rgba(255,0,0,0.06),rgba(0,255,0,0.02),rgba(0,0,255,0.06))] bg-[length:100%_2px,3px_100%] z-0"></div>

